export async function loadInvoice(id: string): Promise<Invoice> {
  const body: unknown = await request(`/invoices/${encodeURIComponent(id)}`);
  if (
    typeof body !== "object" || body === null ||
    typeof (body as Invoice).number !== "string" ||
    typeof (body as Invoice).customer !== "string" ||
    typeof (body as Invoice).totalCents !== "number"
  ) {
    throw new Error(`legacy /invoices/${id} returned an unexpected shape`);
  }
  return body as Invoice;
