import { ListView } from "../components/layout/ListView.tsx";
import { usePayouts, type Payout } from "../data/payouts.ts";

/** Formats integer cents as a decimal amount, e.g. 125000 -> "1250.00". Integer math avoids float rounding. */
export function formatCents(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100);
  const frac = String(abs % 100).padStart(2, "0");
  return `${sign}${whole}.${frac}`;
}

export function PayoutsPage() {
  return (
    <ListView<Payout>
      items={usePayouts()}
      keyOf={(p) => p.id}
      fields={[
        { label: "Date", value: (p) => p.date },
        { label: "Amount", value: (p) => formatCents(p.amountCents), numeric: true },
        { label: "Status", value: (p) => p.status },
      ]}
    />
  );
}
